function canonicalUiText(value){const text=String(value||'').replace(/\s+/g,' ').trim();if(!text)return '';for(const [source,target] of Object.entries(UI_TRANSLATIONS[state.language]||{})){if(target===text)return source}return text}
function t(value){const source=canonicalUiText(value);return UI_TRANSLATIONS[state.language]?.[source]||source}
function currentLanguage(){return ['id','en','zh'].includes(state.language)?state.language:'en'}
function saveLanguage(language){state.language=['id','en','zh'].includes(language)?language:'en';localStorage.setItem('rekarasa:language:v1',state.language);if(state.user?.id)localStorage.setItem('rekarasa:language:v1:'+state.user.id,state.language);document.documentElement.lang=state.language==='zh'?'zh-CN':state.language}
function loadLanguage(){state.language=state.user?.id?localStorage.getItem('rekarasa:language:v1:'+state.user.id)||localStorage.getItem('rekarasa:language:v1')||'en':localStorage.getItem('rekarasa:language:v1')||'en';saveLanguage(state.language)}
let translatingUi=false;
function translateDocument(){if(translatingUi)return;translatingUi=true;try{document.querySelectorAll('body *:not(script):not(style)').forEach(element=>{if(element.closest('[data-no-translate]'))return;for(const attribute of ['placeholder','title','aria-label']){if(!element.hasAttribute(attribute))continue;element.__i18nAttributes=element.__i18nAttributes||{};const original=element.__i18nAttributes[attribute]||canonicalUiText(element.getAttribute(attribute));element.__i18nAttributes[attribute]=original;element.setAttribute(attribute,t(original))}});const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){if(node.parentElement?.closest('script,style,[data-no-translate],textarea,input,.draft-preview,.ready-copy-text,.visual-edit-message,.conversation-brief,.conversation-plan,.conversation-tasks,.history-version-preview'))continue;const raw=node.nodeValue||'',trimmed=raw.replace(/\s+/g,' ').trim();if(!trimmed)continue;node.__i18nSource=node.__i18nSource||canonicalUiText(trimmed);const replacement=t(node.__i18nSource);if(replacement!==trimmed)node.nodeValue=raw.replace(trimmed,replacement)}}finally{translatingUi=false}}
const uiObserver=new MutationObserver(()=>queueMicrotask(translateDocument));uiObserver.observe(document.body,{subtree:true,childList:true,characterData:true});
function setLanguage(language){saveLanguage(language);translateDocument();if(state.user){const route=currentRoute();renderPage().then(translateDocument).catch(()=>translateDocument())}else{authPage(state.authMode||'login');translateDocument()}}

const esc = (s = '') => String(s).replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const date = s => s ? new Date(s).toLocaleDateString(undefined, {month:'short',day:'numeric',year:'numeric'}) : 'No date set';
const time = s => s ? new Date(s).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}) : '';
const labelStatus = s => t(({planned:'Planned',reviewing:'In review',needs_revision:'Revision needed',escalated:'Needs a human',approved_pending_human:'Ready for approval',human_approved:'Human approved'}[s] || s?.replaceAll('_',' ') || 'Draft'));
const AGENT_IDENTITIES = {
 Planner:{name:'Rara',mark:'Ra',role:'Planner',className:'planner'},
 Writer:{name:'Reka',mark:'Re',role:'Writer',className:'writer'},
 Reviewer:{name:'Raya',mark:'Ry',role:'Reviewer',className:'reviewer'}
};
function agentIdentity(role){return Object.values(AGENT_IDENTITIES).find(agent=>String(role||'').toLowerCase().startsWith(agent.role.toLowerCase()))}
function agentLabel(role){const agent=agentIdentity(role);return agent?agent.name+' \u00b7 '+role:String(role||'Agent')}
function agentAvatar(role){const agent=agentIdentity(role);return agent?`<span class="agent-avatar ${agent.className}" aria-hidden="true">${agent.mark}</span>`:''}
function isImageTask(task){return /poster|static ad|image|photo|cover|banner|gambar/i.test(task.format||'')}
function taskStatus(task){return task.status==='human_approved'&&isImageTask(task)?'Copy approved':labelStatus(task.status)}
function formatKey(f){const s=(f||'').toLowerCase();if(/marketplace|listing|shopee|tokopedia/.test(s))return'marketplace';if(/video|script|tiktok|reel/.test(s))return'video';if(/poster|static ad/.test(s))return'poster';if(/hero|product image|gambar/.test(s))return'image';if(/bundle|campaign/.test(s))return'bundle';return'social'}
const icon = name => ({home:'⌂',new:'＋',planner:'▦',projects:'▤',history:'↺',settings:'⚙',menu:'☰',arrow:'↗',close:'×',back:'←'}[name] || '·');
const providerLabel = () => t(({verified:'AI connected',configured_unverified:'Groq unverified',unconfigured:'Groq key not set',invalid_credentials:'Key rejected',schema_rejected:'Schema rejected',unavailable:'Groq unavailable',rate_limited:'Groq rate limited'}[state.providerStatus] || 'Groq unverified'));
function applySession(session){state.devMailbox=!!session.dev_mailbox;state.emailDelivery=session.email_delivery;state.providerStatus=session.provider_status||(session.provider_configured?'configured_unverified':'unconfigured');state.provider=state.providerStatus==='verified';state.model=session.model}
async function api(path, options={}) {
  const headers = {'Content-Type':'application/json', ...(options.headers||{})};
  if (options.method === 'POST' && state.csrf) headers['X-CSRF-Token'] = state.csrf;
  let response;
  try { response = await fetch(path, {...options, headers, credentials:'same-origin'}); }
  catch (error) { if(error.name==='AbortError')throw error;throw new Error('Unable to reach the app. Check the server and try again.'); }
  const result = await response.json().catch(()=>({error:'The server returned an unreadable response.'}));
  if (!response.ok) { if(result.code?.startsWith('provider_')){state.providerStatus=result.code==='provider_auth'?'invalid_credentials':result.code==='provider_unconfigured'?'unconfigured':result.code==='provider_rate_limited'?'rate_limited':result.code==='provider_schema_rejected'?'schema_rejected':'unavailable';state.provider=false;const label=document.querySelector('.provider-pill .nav-text');if(label)label.textContent=providerLabel()} throw Object.assign(new Error(t(result.error || 'Something went wrong.')), {code:result.code, status:response.status}); }
  return result;
}
function toast(message, bad=false) { const box=document.querySelector('#toast'); box.textContent=t(message); box.className=bad?'show bad':'show'; clearTimeout(toast.timer); toast.timer=setTimeout(()=>box.className='',4300); }
function setBusy(el, busy, text='Working…') { if(!el)return; if(busy){el.dataset.prev=el.textContent;el.textContent=t(text);el.disabled=true}else{el.textContent=el.dataset.prev||el.textContent;el.disabled=false;} }
function briefStorageKey(){return state.user?.id?'rekarasa:brief:v1:'+state.user.id:null}
const BRIEF_DRAFT_TTL=24*60*60*1000;
function restoreBriefDraft(){
 if(state.draftOwner!==state.user?.id){state.briefDraft=null;state.draftOwner=state.user?.id;for(const entry of state.attachmentQueue||[])entry.controller?.abort();state.attachmentQueue=[];state.catalogSourcesByProject={}}
 try{const key=briefStorageKey();let draft=state.briefDraft||(key&&JSON.parse(sessionStorage.getItem(key)||'null'));if(!draft||typeof draft.brief!=='string')return;if(!draft.updatedAt){draft={...draft,updatedAt:Date.now()};if(key)sessionStorage.setItem(key,JSON.stringify(draft))}if(Date.now()-draft.updatedAt>=BRIEF_DRAFT_TTL||draft.updatedAt>Date.now()){state.briefDraft=null;if(key)sessionStorage.removeItem(key);return}state.briefDraft=draft}catch{state.briefDraft=null}
}
function storeBriefDraft(draft){
 const previous=state.briefDraft;state.draftOwner=state.user?.id;
 if(draft){const fields=value=>JSON.stringify(Object.fromEntries(Object.entries(value||{}).filter(([key])=>key!=='updatedAt')));draft={...draft,updatedAt:fields(draft)===fields(previous)?previous.updatedAt:Date.now()}}
 state.briefDraft=draft;try{const key=briefStorageKey();if(key){if(draft)sessionStorage.setItem(key,JSON.stringify(draft));else sessionStorage.removeItem(key)}}catch{}return draft
}
function submittedBriefKey(){return state.user?.id?'rekarasa:submitted:v1:'+state.user.id:null}
function savedSubmittedBrief(){try{return JSON.parse(sessionStorage.getItem(submittedBriefKey())||'null')}catch{return null}}
function rememberSubmittedBrief(out,formDraft){state.submittedBrief={out,form:{...formDraft},owner:state.user.id};try{sessionStorage.setItem(submittedBriefKey(),JSON.stringify(state.submittedBrief))}catch{}const form=document.querySelector('#brief-form');if(form){form.dataset.submitted='true';form.querySelector('[name=brief]').value=''}storeBriefDraft(null);state.continueConversation=null;state.editPlan=null}
function briefFormDraft(form){const value=name=>form.querySelector('[name="'+name+'"]')?.value||'';const projectId=value('project_id');return {brief:value('brief'),project_id:projectId,audience:value('audience'),audience_options:[...form.querySelectorAll('[name=audience_options]:checked')].map(input=>input.value),audience_custom:value('audience_custom'),audience_age:value('audience_age'),deadline:value('deadline'),tone:value('tone'),tone_preset:form.querySelector('#tone-preset')?.value||'',custom_format:value('custom_format'),platform_preferences:[...form.querySelectorAll('[name=platform_preferences]:checked')].map(input=>input.value),output_preferences:[...form.querySelectorAll('[name=output_preferences]:checked')].map(input=>input.value),catalog_source_ids:state.catalogSourcesByProject?.[projectId]||(state.briefDraft?.project_id===projectId?state.briefDraft.catalog_source_ids:[])||[],...(state.briefDraft?.edit_plan?{edit_plan:state.briefDraft.edit_plan}:{})}}
function captureBriefDraft(){
 if(!state.user)return;
 const form=document.querySelector('#brief-form');
 if(form){if(form.dataset.submitted)return;return storeBriefDraft(briefFormDraft(form))}
 const home=document.querySelector('#home-brief');if(home)storeBriefDraft({...state.briefDraft,brief:home.value});
}
function clearLocalBrief(){const owner=state.user?.id;storeBriefDraft(null);for(const item of state.attachmentQueue||[])if(item.owner===owner&&item.status==='uploading')item.controller?.abort();state.attachmentQueue=[];state.catalogSourcesByProject={};state.continueConversation=null;state.sessionPlan=null;state.editPlan=null;state.planProject=null}
document.addEventListener('input',event=>{if(event.target.closest('#brief-form')||event.target.id==='home-brief')captureBriefDraft()});
document.addEventListener('change',event=>{if(event.target.closest('#brief-form')&&event.target.type!=='file')captureBriefDraft()});
globalThis.addEventListener('beforeunload',captureBriefDraft);
function agentGuidance(role,message){return `<div class="agent-guidance">${agentAvatar(role)}<p><strong>${esc(agentLabel(role))}</strong><span>${esc(message)}</span></p></div>`}
