const AUDIENCE_OPTIONS=['General Audience','Students','Young Adults','Working Professionals','Entrepreneurs','Parents & Families','Women','Men','Gen Z','Millennials','Business Owners','Online Shoppers','Custom Audience'];
function setupAudience(form){
 const original=form.querySelector('[name=audience]');if(!original)return;const label=original.closest('label');original.type='hidden';if(label){label.firstChild.textContent='Audience (optional)';}
 const picker=document.createElement('details');picker.className='audience-picker';picker.innerHTML='<summary>Choose audience</summary><div class="audience-options">'+AUDIENCE_OPTIONS.map(value=>`<label><input type="checkbox" name="audience_options" value="${esc(value)}"><span>${esc(value)}</span></label>`).join('')+'</div>';original.after(picker);
 const custom=document.createElement('label');custom.className='audience-custom';custom.hidden=true;custom.innerHTML='Custom audience<input name="audience_custom" maxlength="200" placeholder="Describe your audience">';picker.after(custom);
 const update=()=>{const selected=[...picker.querySelectorAll('input:checked')].map(input=>input.value);custom.hidden=!selected.includes('Custom Audience');custom.querySelector('input').required=!custom.hidden;original.value=selected.filter(value=>value!=='Custom Audience').concat(custom.hidden?[]:[custom.querySelector('input').value.trim()]).filter(Boolean).join('; ');picker.querySelector('summary').textContent=selected.length?selected.join(', '):'Choose audience';updateBriefPreferenceCount()};picker.addEventListener('change',update);custom.addEventListener('input',update);picker.addEventListener('keydown',event=>{if(event.key==='Escape'){picker.open=false;picker.querySelector('summary').focus()}});form.updateAudience=update;
}
function restoreBriefForm(form,draft){
 if(!draft)return;for(const name of ['brief','project_id','audience_age','deadline','tone','custom_format']){const input=form.querySelector('[name="'+name+'"]');if(input)input.value=draft[name]||''}
 const choices=draft.audience_options||(draft.audience?['Custom Audience']:[]);for(const box of form.querySelectorAll('[name=audience_options]'))box.checked=choices.includes(box.value);form.querySelector('[name=audience_custom]').value=draft.audience_custom||(draft.audience_options?'':draft.audience)||'';form.updateAudience?.();
 for(const name of ['output_preferences','platform_preferences'])for(const box of form.querySelectorAll('[name='+name+']'))box.checked=(draft[name]||[]).includes(box.value);
 const preset=form.querySelector('#tone-preset');preset.value=draft.tone_preset||'';preset.dataset.applied=BRIEF_TONES[preset.value]||'';preset.dataset.previous=preset.value;const count=document.querySelector('#brief-count');if(count)count.textContent=(draft.brief||'').length+' / 10,000';updateBriefSourceHint();
}
async function editSavedBrief(proposal){
 const saved=state.submittedBrief||savedSubmittedBrief();let draft=saved?.out?.plan_id===proposal.plan_id?saved.form:null;
 if(!draft){const data=await api('/api/conversation?id='+encodeURIComponent(proposal.conversation_id));const c=data.conversation;const prefs=proposal.plan?.brief_preferences||{};draft={brief:c.brief||proposal.brief||'',project_id:proposal.project_id,audience:c.audience||'',tone:c.tone||'',output_preferences:prefs.output_preferences||[],platform_preferences:proposal.plan?.channel_preferences||[],catalog_source_ids:prefs.catalog_source_ids||[],deadline:proposal.plan?.deadline||''}}
 captureBriefDraft();storeBriefDraft({...draft,edit_plan:{plan_id:proposal.plan_id,project_id:proposal.project_id,revision:proposal.plan?.revision||0}});state.sessionPlan=null;state.continueConversation=null;return navigateRoute({page:'new'})
}
const BRIEF_TONES = {
 'Warm and friendly': 'Warm, friendly and approachable; use natural everyday language',
 'Concise and direct': 'Concise and direct; use specific language without inflated claims',
 'Professional': 'Professional and approachable; use plain language without jargon',
 'Playful': 'Playful and light; avoid forced slang and misleading claims',
 'Calm and reassuring': 'Calm and reassuring; avoid pressure and unsupported assurances',
 'Educational': 'Helpful and explanatory; explain clearly without talking down to the audience'
};
function ageRangeProblem(value){const text=String(value||'').trim().toLowerCase().replace(/years?|tahun/g,'').trim().replace(/[\u2013\u2014]/g,'-');if(!text||['semua usia','all ages'].includes(text))return '';const match=text.match(/^(\d{1,3})(?:\s*-\s*(\d{1,3})|\s*\+)?$/);if(!match||Number(match[1])>120||match[2]&&(Number(match[2])>120||Number(match[1])>Number(match[2])))return 'Enter a range such as 20-35 years or 50+, or leave this blank.';return ''}
function briefAudience(audience,age){return [String(audience||'').trim(),age?`Target age: ${age}`:''].filter(Boolean).join('; ')}
function updateBriefPreferenceCount(){const form=document.querySelector('#brief-form'),badge=document.querySelector('#brief-preference-count');if(!form||!badge)return;const values=['audience','audience_age','deadline','tone','custom_format'];const count=values.filter(name=>form.querySelector('[name="'+name+'"]')?.value.trim()).length+form.querySelectorAll('[name=platform_preferences]:checked,[name=output_preferences]:checked').length;badge.textContent=count;badge.hidden=!count}
function updateBriefSourceHint(){const form=document.querySelector('#brief-form');if(!form)return;const folder=form.querySelector('[name=project_id]');folder.dataset.previous=folder.value;const project=state.projects.find(p=>p.id===folder.value);form.querySelector('.brief-project-field small').textContent=project?`${(project.sources||[]).length} fact sources / ${(project.assets||[]).length} photos`:'Choose a project so Rara uses the right sources.';updateBriefPreferenceCount();renderBriefAttachments()}

function projectFolderDialog(onCreated){
 const overlay=document.createElement('div');overlay.className='modal-backdrop';overlay.innerHTML=`<section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="folder-heading"><button type="button" class="modal-close" aria-label="Close">&times;</button><h2 id="folder-heading">New project folder</h2><p>Separate brands keep separate facts, sources and tasks.</p><form id="folder-form"><label>Folder name<input name="name" required maxlength="100" placeholder="For example: Kopi Senja" autocomplete="off"></label><p class="inline-error" role="alert" hidden></p><button class="button primary" type="submit">Create folder</button></form></section>`;
 const previous=document.activeElement;const close=()=>{overlay.remove();previous?.focus()};document.body.append(overlay);overlay.querySelector('.modal-close').onclick=close;overlay.onclick=e=>{if(e.target===overlay)close()};overlay.onkeydown=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const controls=[...overlay.querySelectorAll('button,input')].filter(x=>!x.disabled);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};overlay.querySelector('input').focus();
 overlay.querySelector('form').onsubmit=async e=>{e.preventDefault();const name=overlay.querySelector('input').value.trim();if(!name)return;const button=overlay.querySelector('[type=submit]');setBusy(button,true,'Creating...');let project;try{project=await api('/api/projects',{method:'POST',body:JSON.stringify({name})})}catch(err){const error=overlay.querySelector('[role=alert]');error.hidden=false;error.textContent=err.message;setBusy(button,false);return}close();try{await onCreated(project);toast('Folder created.')}catch(err){toast(err.message,true)}};
}
function catalogPreview(name,preview){return new Promise(resolve=>{
 const overlay=document.createElement('div');overlay.className='modal-backdrop';overlay.innerHTML=`<section class="modal-card catalog-preview" role="dialog" aria-modal="true" aria-labelledby="catalog-title"><h2 id="catalog-title">Check your catalog</h2><p>${esc(name)}: ${preview.rows} rows, ${preview.groups.length} campaign groups. These are your supplied facts, not independently verified claims.</p>${preview.groups.map(group=>`<section><h3>${esc(group.campaign_type)}</h3><ul>${group.items.map(item=>`<li><strong>${esc(item.product_name)}</strong><p>${esc(item.facts)}</p><small>${esc([item.price&&'Price: '+item.price,item.promo&&'Promo: '+item.promo,item.channels&&'Channels: '+item.channels,item.image_filename&&'Image: '+item.image_filename].filter(Boolean).join(' | '))}</small></li>`).join('')}</ul></section>`).join('')}<div class="modal-actions"><button type="button" class="button secondary" id="cancel-catalog">Cancel</button><button type="button" class="button primary" id="confirm-catalog">Use these facts</button></div></section>`;
 const previous=document.activeElement;const finish=answer=>{overlay.remove();previous?.focus();resolve(answer)};document.body.append(overlay);overlay.querySelector('#cancel-catalog').onclick=()=>finish(false);overlay.querySelector('#confirm-catalog').onclick=()=>finish(true);overlay.onkeydown=e=>{if(e.key==='Escape')finish(false);if(e.key==='Tab'){const first=overlay.querySelector('#cancel-catalog'),last=overlay.querySelector('#confirm-catalog');if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};overlay.querySelector('#confirm-catalog').focus();
})}
async function refreshAttachmentProjects(owner){const out=await api('/api/projects');if(state.user?.id!==owner)return;state.projects=out.projects;updateBriefSourceHint();renderBriefAttachments()}
function renderBriefAttachments(){
 const form=document.querySelector('#brief-form'),host=document.querySelector('#attachment-results');if(!form||!host)return;host.replaceChildren();const projectId=form.querySelector('[name=project_id]').value;
 const entries=(state.attachmentQueue||[]).filter(item=>item.owner===state.user?.id&&item.projectId===projectId&&!['saved','removed','canceled'].includes(item.status));
 form.querySelector('[type=submit]').disabled=!!form.dataset.sending||entries.some(item=>['queued','uploading','canceling'].includes(item.status));
 for(const entry of entries){const chip=document.createElement('div');chip.className='brief-file-chip';if(entry.thumbnail){const photo=document.createElement('img');photo.src=entry.thumbnail;photo.alt='Selected '+entry.file.name;chip.append(photo)}const copy=document.createElement('span');const name=document.createElement('strong');name.textContent=entry.file.name;name.title=entry.file.name;const status=document.createElement('small');status.textContent=({selected:'Ready to send',queued:'Queued',uploading:'Uploading...',canceling:'Canceling...',failed:entry.error||'Upload failed'})[entry.status];copy.append(name,status);chip.append(copy);if(entry.status==='failed'){const retry=document.createElement('button');retry.type='button';retry.className='text-button';retry.textContent='Retry on send';retry.onclick=()=>{entry.status='selected';entry.error='';renderBriefAttachments()};chip.append(retry)}const remove=document.createElement('button');remove.type='button';remove.className='brief-chip-remove';remove.innerHTML='&times;';remove.setAttribute('aria-label',(['uploading','queued'].includes(entry.status)?'Cancel upload ':'Remove selected file ')+entry.file.name);remove.title='Remove this attachment';remove.disabled=entry.status==='canceling';remove.onclick=()=>{if(entry.status==='uploading'){entry.status='canceling';entry.controller?.abort()}else{entry.status='removed';entry.thumbnail=null}renderBriefAttachments()};chip.append(remove);host.append(chip)}
}
async function sendBriefAttachments(projectId){
 if(state.uploadWorker)throw Error('Another upload is finishing. Wait a moment, then send your brief again.');
 const batch=(state.attachmentQueue||[]).filter(entry=>entry.owner===state.user?.id&&entry.projectId===projectId&&['selected','failed'].includes(entry.status));
 if(batch.some(entry=>entry.status==='failed'))throw Error('Retry or remove the failed attachment before sending.');
 for(const entry of batch)entry.status='queued';
 await processAttachmentQueue(projectId);
 if(batch.some(entry=>entry.status!=='saved'))throw Error('An attachment was canceled or could not be uploaded. Check the attachments before sending again.');
}
async function uploadBriefAttachments(e){
 const input=e.currentTarget,files=[...input.files];input.value='';const projectId=document.querySelector('#brief-form [name=project_id]')?.value;
 if(!projectId||projectId==='__new_folder__')return toast('Choose a project folder first.',true);if(files.length+(state.attachmentQueue||[]).filter(item=>item.owner===state.user?.id&&item.projectId===projectId&&['selected','failed','queued','uploading'].includes(item.status)).length>20)return toast('Choose up to 20 pending files at a time.',true);
 const replacement=input.id==='replace-brief-photo'?state.replaceAsset:null;state.replaceAsset=null;state.attachmentQueue=state.attachmentQueue||[];
 for(const file of files){if(file.size>5000000){toast(file.name+': maximum 5 MB per file.',true);continue}if(!/\.(xlsx|csv|png|jpe?g)$/i.test(file.name)||replacement&&!/\.(png|jpe?g)$/i.test(file.name)){toast(file.name+': use XLSX, CSV, PNG or JPG.',true);continue}if(replacement&&replacement.projectId!==projectId)continue;const entry={owner:state.user.id,projectId,file,replace:replacement,status:'selected'};state.attachmentQueue.push(entry);if(/\.(png|jpe?g)$/i.test(file.name)){const reader=new FileReader();reader.onload=()=>{if(entry.status==='selected'){entry.thumbnail=reader.result;renderBriefAttachments()}};reader.readAsDataURL(file)}}
 captureBriefDraft();renderBriefAttachments();
}
async function processAttachmentQueue(projectId){
 if(state.uploadWorker)return;state.uploadWorker=true;
 try{let entry;while((entry=(state.attachmentQueue||[]).find(item=>item.status==='queued'&&item.owner===state.user?.id&&(!projectId||item.projectId===projectId)))){
  entry.status='uploading';entry.controller=new AbortController();renderBriefAttachments();
  try{const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Unable to read this file.'));reader.readAsDataURL(entry.file)});if(entry.controller.signal.aborted)throw new DOMException('Canceled','AbortError');
   const payload={project_id:entry.projectId,name:entry.replace?.name||entry.file.name,content_base64:encoded};let result=await api('/api/attachments',{method:'POST',body:JSON.stringify(payload),signal:entry.controller.signal});
   if(result.preview){if(!await catalogPreview(entry.file.name,result.preview)){entry.status='canceled';continue}if(entry.controller.signal.aborted)throw new DOMException('Canceled','AbortError');result=await api('/api/attachments',{method:'POST',body:JSON.stringify({...payload,confirm:true}),signal:entry.controller.signal})}
   if(state.user?.id!==entry.owner)continue;
   if(result.catalog){entry.catalog=true;state.catalogSourcesByProject=state.catalogSourcesByProject||{};state.catalogSourcesByProject[entry.projectId]=[...new Set([...(state.catalogSourcesByProject[entry.projectId]||[]),...result.source_ids])]}
   if(entry.replace&&result.asset&&result.asset.id!==entry.replace.id)await api('/api/archive-asset',{method:'POST',body:JSON.stringify({asset_id:entry.replace.id})});entry.status='saved';await refreshAttachmentProjects(entry.owner);captureBriefDraft();
  }catch(err){if(state.user?.id!==entry.owner)continue;entry.status=err.name==='AbortError'?'canceled':'failed';entry.error=err.message;if(err.name==='AbortError'){await refreshAttachmentProjects(entry.owner).catch(()=>{});toast('Upload stopped. If it had already finished, manage the saved file in Project details.')}}finally{renderBriefAttachments()}
 }}finally{state.uploadWorker=false;renderBriefAttachments()}
}

