async function renderSelectedCompositionReference(composition){
 if(!composition?.preview_url||!composition.render_sha256)return null;
 const response=await fetch(composition.preview_url,{credentials:'same-origin',cache:'no-store'});
 if(!response.ok)throw new Error('The selected visual could not be loaded. Reopen it and try again.');
 const blob=await response.blob();
 const source=await new Promise((resolve,reject)=>{
  const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('The selected visual could not be read.'));reader.readAsDataURL(blob);
 });
 const image=await new Promise((resolve,reject)=>{const item=new Image();item.onload=()=>resolve(item);item.onerror=()=>reject(new Error('The selected visual could not be rendered.'));item.src=source});
 const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;
 const context=canvas.getContext('2d',{alpha:true});if(!context)throw new Error('This browser cannot prepare the selected visual for editing.');
 context.drawImage(image,0,0);
 const dataUrl=canvas.toDataURL('image/png');
 return {reference_base64:dataUrl.split(',',2)[1],source_render_sha256:composition.render_sha256};
}
