async function downloadVisual(composition,type,button){
 if(!composition||composition.status!=='human_approved'||!composition.download_url){showVisualError('Approve this visual first.');return}
 if(!['png','svg'].includes(type))return;
 const taskId=state.activeTask?.id;
 if(composition.task_id&&composition.task_id!==taskId){showVisualError('Reopen the selected image.');return}
 setBusy(button,true,'Downloading...');
 try{
  const response=await fetch(composition.download_url,{credentials:'same-origin'});
  if(!response.ok){const error=await response.json().catch(()=>({}));throw new Error(error.error||'Visual approval is required before export.')}
  let blob=await response.blob();
  if(type==='png'){
   const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read the composed visual.'));reader.readAsDataURL(blob)});
   const image=await new Promise((resolve,reject)=>{const item=new Image();item.onload=()=>resolve(item);item.onerror=()=>reject(new Error('Could not render this visual as PNG. Download SVG instead.'));item.src=dataUrl});
   const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;canvas.getContext('2d').drawImage(image,0,0);
   blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('PNG export failed. Download SVG instead.');
  }
  const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='rekarasa-image-'+composition.image_id+'-copy-'+composition.version_id+'-visual-'+composition.id+'.'+type;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Approved visual downloaded as '+type.toUpperCase()+'.');
 }catch(e){showVisualError(e.message)}finally{setBusy(button,false)}
}
