 overlay.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.currentTarget.querySelector('[type=submit]');setBusy(button,true,'Saving...');error.hidden=true;try{await api('/api/password/reset',{method:'POST',body:JSON.stringify({email:state.user.email,...Object.fromEntries(new FormData(event.currentTarget))})});close();clearLocalBrief();state.user=null;state.csrf=null;authPage();toast('Password updated. Sign in with your new password.')}catch(err){error.textContent=err.message;error.hidden=false;setBusy(button,false)}};
 overlay.onkeydown=event=>{if(event.key==='Escape'){event.preventDefault();close()}if(event.key==='Tab'){const items=[...overlay.querySelectorAll('button:not(:disabled),input:not(:disabled)')];const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}};
