const baseWorkbenchPage=workbenchPage;
function sentences(text){return String(text||'').replace(/([.!?])\s+/g,'$1\n').split('\n').map(line=>line.trim()).filter(Boolean)}
function sentenceDiff(before,after){
 const a=sentences(before),b=sentences(after),n=a.length,m=b.length;
 const table=Array.from({length:n+1},()=>new Uint16Array(m+1));
 for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)table[i][j]=a[i]===b[j]?table[i+1][j+1]+1:Math.max(table[i+1][j],table[i][j+1]);
 const out=[];let i=0,j=0;
 while(i<n&&j<m){if(a[i]===b[j]){out.push({type:'same',text:a[i]});i++;j++}else if(table[i+1][j]>=table[i][j+1]){out.push({type:'del',text:a[i]});i++}else{out.push({type:'add',text:b[j]});j++}}
 while(i<n)out.push({type:'del',text:a[i++]});
 while(j<m)out.push({type:'add',text:b[j++]});
 return out;
}
function versionDiffPanel(task){
 const versions=task.versions||[];
 if(versions.length<2)return;
 const list=document.querySelector('.version-list');
 const section=document.querySelector('.version-section');
 if(!list||!section)return;
 const previous=versions.at(-2),latest=versions.at(-1);
 const changed=sentenceDiff(previous.content,latest.content).filter(part=>part.type!=='same').length;
 const box=document.createElement('details');
 box.className='version-diff';
 box.open=changed>0;
 const summary=document.createElement('summary');
 summary.textContent=changed?`What changed · v${previous.version} → v${latest.version} · ${changed} line${changed===1?'':'s'}`:`What changed · v${previous.version} → v${latest.version} · identical wording`;
 const body=document.createElement('div');
 body.className='diff-body';
 for(const part of sentenceDiff(previous.content,latest.content)){
  if(part.type==='same'&&body.childElementCount>6)continue;
  const line=document.createElement('p');
  line.className='diff-line '+part.type;
  line.textContent=(part.type==='add'?'+ ':part.type==='del'?'\u2212 ':'\u00a0\u00a0')+part.text;
  body.append(line);
 }
 box.append(summary,body);
 list.before(box);
}
workbenchPage = async function(id) {
 await baseWorkbenchPage(id);
 const task = state.activeTask;
 if (!task || task.id !== id) return;

 const version = state.displayVersion;
 const latest = task.versions?.at(-1);
 const historical = version && version.id !== latest?.id;
 versionDiffPanel(task);
 simplifyWorkbench(task, version);

 document.querySelectorAll('[data-editor-version]').forEach(button => {
  button.onclick = () => openTask(task.id, button.dataset.editorVersion);
 });
 if (version) {
  const label = document.querySelector('.draft-toolbar .eyebrow');
  if (label) label.textContent = 'SAVED VERSION';
  const pill = document.querySelector('.draft-toolbar .version-pill');
  if (pill) pill.textContent = 'v' + version.version;
 }

 if (historical) {
  document.querySelectorAll('#human-approve, #human-reject, #remediate, #review-latest, #generate-one, #retry-generate, #export-draft, #download-draft, #set-dates, .workbench-controls .status-chip, .human-gate, .remediation-box, .escalation-note').forEach(node => node.remove());
  const status = version.human_approved
   ? (isImageTask(task) ? 'Copy approved' : 'Human approved')
   : ({pass: 'Review passed', fail: 'Revision needed', needs_revision: 'Revision needed', needs_human_review: 'Needs a human', pending: 'Awaiting review', review_error: 'Review unavailable'}[version.review_status] || labelStatus(version.review_status));
  const headingStatus = document.querySelector('.workbench-heading p');
  if (headingStatus) headingStatus.textContent = status + ' · Version ' + version.version
   + (task.deadline ? ' · Due ' + date(task.deadline) : '')
   + (task.publish_at ? ' · Planned ' + date(task.publish_at) : '')
   + (!task.deadline && !task.publish_at ? ' · No date set' : '');
  const note = document.querySelector('.ready-output-status');
  if (note) note.textContent = 'Earlier saved version. Edit as a new version, or return to the latest version to approve.';

  const form = document.querySelector('#edit-form');
  const toggle = document.querySelector('#edit-toggle');
  if (form) {
   form.hidden = true;
   form.classList.add('hidden');
   form.elements.content.value = version.content;
  }
  if (toggle && form) {
   toggle.disabled = false;
   toggle.textContent = 'Edit as new version';
   toggle.onclick = () => {
    form.elements.content.value = version.content;
    form.hidden = false;
    form.classList.remove('hidden');
    document.querySelector('#draft-display')?.classList.add('hidden');
   };
  }
  const back = document.createElement('button');
  back.type = 'button';
  back.className = 'button secondary';
  back.textContent = 'Return to latest version';
  back.onclick = () => openTask(task.id);
  document.querySelector('.workbench-heading')?.append(back);
 }

 const visual = document.querySelector('.visual-studio');
 if (historical) {
  if (visual) visual.hidden = true;
  document.querySelector('.open-image-stage')?.remove();
 } else if (isImageTask(task) && (version || state.selectedVersion) && visual) {
  visual.hidden = false;
  document.querySelector('.open-image-stage')?.remove();
  document.querySelector('.workbench-grid')?.before(visual);
  const selectedImageId = state.selectedVersion && !task.versions?.some(item => item.id === state.selectedVersion)
   ? state.selectedVersion : null;
  await loadTaskImages(task, selectedImageId);
 }
};
